func (h *NATSMonitorHandler) GetOverview(c *fiber.Ctx) error {
	ctx, cancel := context.WithTimeout(c.UserContext(), 3*time.Second)
	defer cancel()

	var (
		varz    map[string]interface{}
		jsz     map[string]interface{}
		connz   map[string]interface{}
		errVarz error
		errJsz  error
		errConn error
		wg      sync.WaitGroup
	)

	wg.Add(3)
	go func() {
		defer wg.Done()
		errVarz = h.fetchJSON(ctx, "/varz", &varz)
	}()
	go func() {
		defer wg.Done()
		errJsz = h.fetchJSON(ctx, "/jsz?streams=true&config=true&consumers=true", &jsz)
	}()
	go func() {
		defer wg.Done()
		errConn = h.fetchJSON(ctx, "/connz", &connz)
	}()
	wg.Wait()

